"""Wire the CareerBuddy runtime into the CDK stack generated by `agentcore create`.

Grants the runtime's execution role read/write on the existing DynamoDB table (least
privilege: that table only) and passes configuration as environment variables.
Idempotent. Usage: python3 patch_cdk.py <cdk-stack.ts> <table-name> <runtime-name> <model-id>
"""
import re
import sys
from pathlib import Path

path, table, runtime, model_id = Path(sys.argv[1]), sys.argv[2], sys.argv[3], sys.argv[4]
source = path.read_text()
MARKER = "// CareerBuddy runtime wiring"
# The generated stack mentions the import inside a comment; require a real import line.
if not re.search(r"^import \* as dynamodb from 'aws-cdk-lib/aws-dynamodb';", source, re.M):
    source = "import * as dynamodb from 'aws-cdk-lib/aws-dynamodb';\n" + source
if MARKER in source:
    path.write_text(source)
    print("CDK stack already wired for CareerBuddy")
    raise SystemExit(0)
anchor = "this.application = new AgentCoreApplication(this, 'Application', props.application);"
if anchor not in source:
    raise SystemExit("Unexpected cdk-stack.ts layout; add the grant manually (see README).")
wiring = f"""{anchor}

    {MARKER}: least-privilege access to the existing table, config via env vars.
    const careerBuddyTable = dynamodb.Table.fromTableName(this, 'CareerBuddyTable', '{table}');
    const careerBuddy = this.application.runtime('{runtime}');
    careerBuddy.grantReadWrite(careerBuddyTable);
    careerBuddy.addEnvironmentVariable('SKILLPILOT_REPOSITORY', 'dynamodb');
    careerBuddy.addEnvironmentVariable('SKILLPILOT_TABLE_NAME', '{table}');
    careerBuddy.addEnvironmentVariable('SKILLPILOT_AI_MODE', 'bedrock');
    careerBuddy.addEnvironmentVariable('SKILLPILOT_MODEL_ID', '{model_id}');"""
path.write_text(source.replace(anchor, wiring, 1))
print(f"Wired {runtime} to table {table}")
